-- Generated by scripts/build-starters.mts. Edit app/lib/starters/*.ts and regenerate.

insert into public.starter_characters (key, game, sort, name, faction, portrait, summary, sheet)
values
  ('vtm-trixx-laveau', 'vampire', 1, 'Trixx Laveau', 'brujah', '/Female1.jpg', 'Anarch enforcer and true believer of The Cause. Right hand to the Anarch leader. If you don''t want trouble, stay out of her way.', '{"profile":{"name":"Trixx Laveau","concept":"Punk singer turned Anarch enforcer","chronicle":"Glasgow by Night","ambition":"Break the Camarilla’s hold on the East End.","desire":"Play one more gig at the Barrowland, just once.","predator":"Alleycat","sire":"Rab “the Boot” MacRae","clan":"Brujah","generation":"12th","sect":"Anarch","bloodSurge":"Add 2 dice","mendAmount":"1 point of Superficial damage","powerBonus":"None","rouseReroll":"Level 1 Disciplines","baneSeverity":"2","feedingPenalty":"None"},"attributes":{"Strength":4,"Dexterity":3,"Stamina":3,"Charisma":2,"Manipulation":2,"Composure":1,"Intelligence":2,"Wits":3,"Resolve":2},"skills":{"Brawl":{"dots":3,"specialty":"Bar fights"},"Intimidation":{"dots":3,"specialty":"Stickups"},"Streetwise":{"dots":3},"Athletics":{"dots":2},"Melee":{"dots":2},"Drive":{"dots":2},"Leadership":{"dots":2},"Awareness":{"dots":2},"Firearms":{"dots":1},"Larceny":{"dots":1},"Stealth":{"dots":1},"Insight":{"dots":1},"Subterfuge":{"dots":1},"Politics":{"dots":1},"Performance":{"dots":1,"specialty":"Punk vocals"}},"disciplines":[{"name":"Potence","dots":2,"powers":["Lethal Body","Prowess"]},{"name":"Presence","dots":1,"powers":["Daunt"]},{"name":"Celerity","dots":1,"powers":["Rapid Reflexes"]}],"trackers":{"health":6,"willpower":3,"humanity":6,"hunger":1},"bloodPotency":1,"bane":"Violence: when she rolls to resist a fury frenzy, she subtracts dice equal to her Bane Severity (2).","tenets":"Elysium is neutral ground: no violence, no feeding, no Disciplines on the unwilling inside it.\nThe Masquerade comes before every grudge.\nNo one is Embraced without the Prince’s leave, Anarch or not.","advantages":[{"name":"Contacts","dots":3,"kind":"background","note":"Criminal underworld: fences, bouncers, a getaway driver","source":"Predator type"},{"name":"Allies","dots":3,"kind":"background","note":"The Rack, her Anarch crew"},{"name":"Haven","dots":1,"kind":"background","note":"Flat above a tattoo parlour in Calton"},{"name":"Resources","dots":1,"kind":"background","note":"Bar shifts and cash jobs"},{"name":"Mask","dots":1,"kind":"background","note":"Tricia Lavelle, bartender"},{"name":"Status","dots":1,"kind":"background","note":"Anarchs of Glasgow"},{"name":"Enemy","dots":1,"kind":"flaw","note":"The Sheriff’s ghoul, whose nose she broke"},{"name":"Suspect","dots":1,"kind":"flaw","note":"The Camarilla watches her"}],"convictions":[{"conviction":"Never sell out the Movement.","touchstone":"Mackie Doyle, her old bandmate, who still plays the Barrowland"},{"conviction":"Nobody hurts kids on my watch.","touchstone":"Iona, her twelve-year-old niece"}],"biography":{"born":"1987-03-14","turned":"2009-11-02","appearance":"Twin buns, black bangs, red eyeshadow, a spiked choker and a throat covered in tattoos. Leather jacket, always.","features":"Her eyes still flash red when she loses her temper.","history":"Tricia Lavelle fronted a Glasgow punk band and broke more bottles than records. Rab MacRae, a Brujah firebrand, Embraced her after a riot outside a gig she started on purpose. When Rab met the sun, she took his place in the Rack. Now she collects debts for the Anarch Baron, keeps the East End off the Camarilla’s books, and has never once backed down."}}'::jsonb),
  ('vtm-blake-janssen', 'vampire', 2, 'Blake Janssen', 'nosferatu', '/Nosferatu.jpeg', 'Nosferatu spymaster, he knows everything about everyone. He is the keeper of secrets and the master of the shadows.', '{"profile":{"name":"Blake Janssen","concept":"Spymaster under the city","chronicle":"Glasgow by Night","ambition":"Become the one Kindred the Prince cannot afford to lose.","desire":"Find out who leaked his last file.","predator":"Sandman","sire":"Old Morag of the Subway","clan":"Nosferatu","generation":"12th","sect":"Camarilla","bloodSurge":"Add 2 dice","mendAmount":"1 point of Superficial damage","powerBonus":"None","rouseReroll":"Level 1 Disciplines","baneSeverity":"2","feedingPenalty":"None"},"attributes":{"Strength":2,"Dexterity":3,"Stamina":2,"Charisma":1,"Manipulation":2,"Composure":2,"Intelligence":4,"Wits":3,"Resolve":3},"skills":{"Investigation":{"dots":4,"specialty":"Surveillance"},"Stealth":{"dots":3,"specialty":"Break-in"},"Technology":{"dots":3},"Streetwise":{"dots":3},"Larceny":{"dots":2},"Awareness":{"dots":2},"Subterfuge":{"dots":2},"Academics":{"dots":1,"specialty":"City records"},"Insight":{"dots":1},"Firearms":{"dots":1}},"disciplines":[{"name":"Obfuscate","dots":3,"powers":["Cloak of Shadows","Unseen Passage","Ghost in the Machine"]},{"name":"Animalism","dots":1,"powers":["Bond Famulus"]}],"trackers":{"health":5,"willpower":5,"humanity":7,"hunger":1},"bloodPotency":1,"bane":"Repulsiveness: he can never pass for human. Rolls to disguise himself as human fail, and his Charisma-based social rolls with mortals suffer a penalty equal to his Bane Severity (2).","tenets":"Elysium is neutral ground: no violence, no feeding, no Disciplines on the unwilling inside it.\nThe Masquerade comes before every grudge.\nNo one is Embraced without the Prince’s leave, Anarch or not.","advantages":[{"name":"Resources","dots":1,"kind":"background","note":"Selling information","source":"Predator type"},{"name":"Haven","dots":2,"kind":"background","note":"A sealed-off stretch of the old Subway tunnels"},{"name":"Contacts","dots":3,"kind":"background","note":"A council clerk, a police dispatcher and a teenage hacker"},{"name":"Retainer","dots":1,"kind":"background","note":"Wee Malky, a ghouled courier"},{"name":"Mask","dots":1,"kind":"background","note":"Paperwork for “Brian Jansen”, who never shows up in person"},{"name":"Enemy","dots":1,"kind":"flaw","note":"A Tremere he is blackmailing"},{"name":"Dark Secret","dots":1,"kind":"flaw","note":"He holds proof the Prince once broke the Masquerade"}],"convictions":[{"conviction":"Information is never destroyed, only kept.","touchstone":"Elspeth Gray, an archivist at the Mitchell Library"},{"conviction":"Never let a mortal see his face.","touchstone":"His sister Karen, who thinks he died in 1998"}],"biography":{"born":"1957-06-30","turned":"1998-02-11","appearance":"A ruined, scarred face, thin hair slicked back, and a carefully pressed old suit.","features":"He smells of damp stone and printer toner.","history":"Blake was a private investigator who followed the wrong man into the Subway tunnels. Old Morag decided his talents were wasted on the living. Twenty-five years on, his archive under the city holds a file on nearly every Kindred in Glasgow. He sells what he must, keeps what matters, and has never sold the same secret twice."}}'::jsonb),
  ('vtm-claire-voyant', 'vampire', 3, 'Claire Voyant', 'malkavian', '/Malkavian.jpg', 'Bearer of headaches, a Malkavian seer, she is the local oracle. She is cryptic, but her predictions are always accurate.', '{"profile":{"name":"Claire Voyant","concept":"Tarot reader and the city’s oracle","chronicle":"Glasgow by Night","ambition":"Stop the vision of the burning cathedral from coming true.","desire":"One night without the headaches.","predator":"Consensualist","sire":"Mr. Pemberton (no one has seen him since)","clan":"Malkavian","generation":"12th","sect":"Camarilla","bloodSurge":"Add 2 dice","mendAmount":"1 point of Superficial damage","powerBonus":"None","rouseReroll":"Level 1 Disciplines","baneSeverity":"2","feedingPenalty":"None"},"attributes":{"Strength":1,"Dexterity":2,"Stamina":2,"Charisma":3,"Manipulation":2,"Composure":2,"Intelligence":3,"Wits":4,"Resolve":3},"skills":{"Occult":{"dots":3,"specialty":"Prophecy"},"Awareness":{"dots":2},"Insight":{"dots":2},"Persuasion":{"dots":2},"Medicine":{"dots":2,"specialty":"Phlebotomy"},"Academics":{"dots":2,"specialty":"Psychology"},"Etiquette":{"dots":2},"Investigation":{"dots":2},"Subterfuge":{"dots":2},"Athletics":{"dots":1},"Stealth":{"dots":1},"Drive":{"dots":1},"Science":{"dots":1,"specialty":"Astronomy"},"Politics":{"dots":1},"Streetwise":{"dots":1},"Performance":{"dots":1,"specialty":"Tarot readings"},"Leadership":{"dots":1},"Animal Ken":{"dots":1},"Technology":{"dots":1}},"disciplines":[{"name":"Auspex","dots":3,"powers":["Heightened Senses","Premonition","Scry the Soul"]},{"name":"Dominate","dots":1,"powers":["Cloud Memory"]}],"trackers":{"health":5,"willpower":5,"humanity":8,"hunger":1},"bloodPotency":1,"bane":"Fractured Perspective: when she suffers a Bestial Failure or a Compulsion, her derangement takes hold, and she takes a penalty equal to her Bane Severity (2) to one category of dice pools for the scene.","tenets":"Elysium is neutral ground: no violence, no feeding, no Disciplines on the unwilling inside it.\nThe Masquerade comes before every grudge.\nNo one is Embraced without the Prince’s leave, Anarch or not.","advantages":[{"name":"Herd","dots":2,"kind":"background","note":"Regular clients who come back for readings, and give"},{"name":"Resources","dots":2,"kind":"background","note":"The tarot parlour on Byres Road"},{"name":"Haven","dots":1,"kind":"background","note":"The back room of the parlour, blacked out"},{"name":"Contacts","dots":1,"kind":"background","note":"A nurse at the Western Infirmary"},{"name":"Fame","dots":1,"kind":"background","note":"Known as the West End’s best reader"},{"name":"Dark Secret","dots":1,"kind":"flaw","note":"Masquerade breacher: a client saw her feed","source":"Predator type"},{"name":"Prey Exclusion","dots":1,"kind":"flaw","note":"Never feeds on the unwilling","source":"Predator type"},{"name":"Stalkers","dots":1,"kind":"flaw","note":"A client who believes she is a saint"},{"name":"Enemy","dots":1,"kind":"flaw","note":"A Second Inquisition informant who watched the parlour"}],"convictions":[{"conviction":"Always tell them the truth, even when it hurts.","touchstone":"Dr Harriet Sim, her old psychiatrist"},{"conviction":"Never take blood from anyone who didn’t say yes.","touchstone":"Tam, the busker outside the parlour"}],"biography":{"born":"1979-10-31","turned":"2004-01-06","appearance":"Pale, hair pinned up loosely, long dark coat with fur cuffs. She presses her temples when the visions come.","features":"Never sits with her back to a mirror.","history":"Claire heard voices long before her Embrace, and her psychiatrist believed she was getting better. Then Mr. Pemberton came for a reading, told her the cards were wrong, and made sure the voices never stopped. Now she reads tarot on Byres Road for mortals by day’s end and for Kindred after midnight. Her predictions are cryptic, uncomfortable and, so far, always right."}}'::jsonb),
  ('wta-grey-fang', 'werewolf', 1, 'Grey-Fang', 'Red Talons', '/portraits/garou-crinos.webp', 'An Ahroun who stopped counting the hunters he has buried. Speaks rarely, and only to the pack.', '{"profile":{"name":"Grey-Fang","concept":"Wolf-born warrior of the high fells","chronicle":"Glasgow by Night","pack":"The Rail-Yard Howlers","patron":"Griffin","tribe":"Red Talons","auspice":"Ahroun","ambition":"Drive Endron’s survey teams out of the Campsie Fells.","desire":"To run with the wolves of his birth one more time.","breed":"Lupus"},"attributes":{"Strength":4,"Dexterity":3,"Stamina":3,"Charisma":1,"Manipulation":2,"Composure":2,"Intelligence":2,"Wits":3,"Resolve":2},"skills":{"Brawl":{"dots":3,"specialty":"Tackles"},"Survival":{"dots":3,"specialty":"Tracking"},"Athletics":{"dots":3},"Stealth":{"dots":2},"Awareness":{"dots":2},"Intimidation":{"dots":2,"specialty":"Snarling"},"Insight":{"dots":2},"Animal Ken":{"dots":2},"Melee":{"dots":1},"Investigation":{"dots":1},"Occult":{"dots":1},"Streetwise":{"dots":1},"Medicine":{"dots":1},"Leadership":{"dots":1},"Etiquette":{"dots":1}},"renown":{"glory":1,"honor":2,"wisdom":0},"gifts":[{"name":"Staredown","source":"Native","renown":"Honor"},{"name":"Razor Claws","source":"Auspice","renown":"Glory"},{"name":"Hidden Killer","source":"Tribe","renown":"Honor"}],"rites":[],"trackers":{"health":6,"willpower":4,"rage":1,"harano":0,"hauglosk":0},"advantages":[{"name":"Allies","dots":3,"kind":"background","note":"The wolf pack of the Campsie Fells"},{"name":"Haven","dots":2,"kind":"background","note":"A den under a fallen larch"},{"name":"Mask","dots":1,"kind":"background","note":"“Greg Fang”, a drifter with no fixed address"},{"name":"Contacts","dots":1,"kind":"background","note":"A ranger who looks the other way"},{"name":"Illiterate","dots":1,"kind":"flaw","note":"Wolf-born; human letters mean nothing to him"},{"name":"Enemy","dots":1,"kind":"flaw","note":"An Endron security contractor who lost an arm to him"}],"convictions":[{"conviction":"The pack eats before I do.","touchstone":"Ailsa Reid, the ranger who once set him free from a snare"},{"conviction":"No hunter who harms a cub walks away.","touchstone":"The grey she-wolf who raised him"}],"biography":{"born":"2014-04-02","turned":"2016-10-17","appearance":"In war form a gaunt, bristling giant with a muzzle full of broken teeth. As a man, wiry and grey-haired, with eyes that never quite settle.","features":"A leather cord of hunters’ teeth around his neck.","history":"Born to a wolf pack the Garou kept hidden in the fells, Grey-Fang underwent the First Change when hunters gunned down his litter-mates. The Red Talons took him in and taught him that humans would end the wild. The Rail-Yard Howlers taught him that some of them are worth protecting. He has not decided which lesson is true."}}'::jsonb),
  ('wta-rosa-vex', 'werewolf', 2, 'Rosa "Static" Vex', 'Glass Walkers', '/portraits/garou-punk.webp', 'A Ragabash who hacks Endron payrolls for fun and spirit-talks the city grid for the pack.', '{"profile":{"name":"Rosa “Static” Vex","concept":"Hacker trickster of the city grid","chronicle":"Glasgow by Night","pack":"The Rail-Yard Howlers","patron":"Cockroach","tribe":"Glass Walkers","auspice":"Ragabash","ambition":"Expose Endron’s Glasgow projects on every screen in the city.","desire":"To be the one who gets away with it, again.","breed":"Homid"},"attributes":{"Strength":2,"Dexterity":3,"Stamina":2,"Charisma":2,"Manipulation":3,"Composure":1,"Intelligence":3,"Wits":4,"Resolve":2},"skills":{"Technology":{"dots":4,"specialty":"Hacking"},"Larceny":{"dots":3,"specialty":"Security systems"},"Subterfuge":{"dots":3,"specialty":"Impersonation"},"Streetwise":{"dots":3},"Stealth":{"dots":2},"Investigation":{"dots":2},"Finance":{"dots":2},"Brawl":{"dots":1},"Firearms":{"dots":1},"Occult":{"dots":1}},"renown":{"glory":1,"honor":0,"wisdom":2},"gifts":[{"name":"Penumbral Senses","source":"Native","renown":"Wisdom"},{"name":"Gremlins","source":"Auspice","renown":"Glory"},{"name":"Spider’s Song","source":"Tribe","renown":"Wisdom"}],"rites":[],"trackers":{"health":5,"willpower":3,"rage":1,"harano":0,"hauglosk":0},"advantages":[{"name":"Contacts","dots":3,"kind":"background","note":"Hackers, a phone-shop fence and a bored IT admin at Endron"},{"name":"Resources","dots":2,"kind":"background","note":"Freelance security “testing”"},{"name":"Haven","dots":1,"kind":"background","note":"A server closet in a squatted office block"},{"name":"Mask","dots":1,"kind":"background","note":"Six online identities and one real one"},{"name":"Enemy","dots":1,"kind":"flaw","note":"Endron’s cyber-security team"},{"name":"Addiction","dots":1,"kind":"flaw","note":"Energy drinks; without them she shakes"}],"convictions":[{"conviction":"Every lock deserves to be picked.","touchstone":"Dev Okafor, her flatmate from her uni days"},{"conviction":"Never leave a packmate in the dark.","touchstone":"Her gran in Govan, who still calls her Rosie"}],"biography":{"born":"1999-08-22","turned":"2016-05-03","appearance":"Bleached hair with a red streak, a pale grey complexion, tattoos and chains, and a stack of keycards on a lanyard.","features":"Lights flicker when she is angry.","history":"Rosa’s First Change hit her in the middle of a sixth-year computing exam. The Glass Walkers found her before the police did and taught her that the city has spirits too, living in its cables and signals. She joined the Howlers after hacking their caern’s security system on a dare, and has been their eyes on Endron ever since."}}'::jsonb),
  ('wta-old-tom-marrow', 'werewolf', 3, 'Old Tom Marrow', 'Bone Gnawers', '/portraits/garou-drifter.webp', 'A Galliard who sings the forgotten caerns of the rail yards. Knows every stray by name.', '{"profile":{"name":"Old Tom Marrow","concept":"Busker, storyteller and keeper of the rail-yard caern","chronicle":"Glasgow by Night","pack":"The Rail-Yard Howlers","patron":"Rat","tribe":"Bone Gnawers","auspice":"Galliard","ambition":"Wake the old caern under Cowlairs before the developers pour concrete on it.","desire":"A dry place to sleep and an audience who listens.","breed":"Homid"},"attributes":{"Strength":2,"Dexterity":2,"Stamina":3,"Charisma":4,"Manipulation":2,"Composure":3,"Intelligence":2,"Wits":3,"Resolve":1},"skills":{"Performance":{"dots":3,"specialty":"Ballads"},"Streetwise":{"dots":2,"specialty":"Rail yards"},"Survival":{"dots":2},"Animal Ken":{"dots":2,"specialty":"Stray dogs"},"Persuasion":{"dots":2},"Insight":{"dots":2},"Occult":{"dots":2},"Awareness":{"dots":2},"Brawl":{"dots":2},"Athletics":{"dots":1},"Stealth":{"dots":1},"Larceny":{"dots":1},"Drive":{"dots":1},"Etiquette":{"dots":1},"Leadership":{"dots":1},"Subterfuge":{"dots":1},"Medicine":{"dots":1},"Academics":{"dots":1},"Melee":{"dots":1}},"renown":{"glory":0,"honor":1,"wisdom":2},"gifts":[{"name":"The Howl Carries","source":"Native","renown":"Wisdom"},{"name":"Howl of Assembly","source":"Auspice","renown":"Honor"},{"name":"Blissful Ignorance","source":"Tribe","renown":"Wisdom"}],"rites":[],"trackers":{"health":6,"willpower":4,"rage":1,"harano":0,"hauglosk":0},"advantages":[{"name":"Allies","dots":2,"kind":"background","note":"The rough sleepers of the rail yards"},{"name":"Contacts","dots":2,"kind":"background","note":"A soup-kitchen cook and a Network Rail signalman"},{"name":"Haven","dots":1,"kind":"background","note":"A disused signal box"},{"name":"Fame","dots":1,"kind":"background","note":"Every busker on Buchanan Street knows his songs"},{"name":"Mask","dots":1,"kind":"background","note":"Thomas Marrow, pensioner, of no fixed abode"},{"name":"Addiction","dots":1,"kind":"flaw","note":"Whisky, to quiet the old songs"},{"name":"Destitute","dots":1,"kind":"flaw","note":"Owns a fiddle, a coat and a dog"}],"convictions":[{"conviction":"Every story deserves to be remembered.","touchstone":"Bonnie, his three-legged collie"},{"conviction":"Share the last of what you have.","touchstone":"Sister Agnes at the Calton soup kitchen"}],"biography":{"born":"1958-12-01","turned":"1972-07-19","appearance":"Wild grey hair and beard, a threadbare linen jacket over a bare chest, bone charms on a string, a fiddle on his back.","features":"Dogs follow him through the city without being called.","history":"Tom ran away from a children’s home at thirteen and Changed for the first time in a goods wagon at Cowlairs. The Bone Gnawers of the yards raised him on songs about caerns the city has buried. Fifty years later he is the one who remembers them all, and the Howlers are the first pack he thinks might help him wake one."}}'::jsonb),
  ('htr-dez-mcallister', 'hunter', 1, 'Dez McAllister', 'Inquisitive', '/portraits/hunter-flannel.webp', 'Ex-crime-scene photographer. Keeps the cell’s evidence board and refuses to stop asking questions.', '{"profile":{"name":"Dez McAllister","concept":"Crime-scene photographer who saw too much","chronicle":"Glasgow by Night","cell":"The Kelvin Street Cell","creed":"Inquisitive","drive":"Curiosity","ambition":"Prove to the world what is really feeding in the East End.","desire":"One photograph that nobody can explain away."},"attributes":{"Strength":2,"Dexterity":3,"Stamina":2,"Charisma":2,"Manipulation":2,"Composure":3,"Intelligence":3,"Wits":4,"Resolve":1},"skills":{"Investigation":{"dots":4,"specialty":"Crime scenes"},"Craft":{"dots":3,"specialty":"Photography"},"Awareness":{"dots":3,"specialty":"The detail that’s wrong"},"Technology":{"dots":3},"Stealth":{"dots":2},"Insight":{"dots":2},"Streetwise":{"dots":2},"Drive":{"dots":1},"Larceny":{"dots":1},"Occult":{"dots":1}},"edges":[{"name":"Library","perks":["Who They Were: trace a creature back to the person it used to be"]},{"name":"Sense the Unnatural","perks":[]}],"trackers":{"health":5,"willpower":4,"desperation":1,"danger":0},"advantages":[{"name":"Contacts","dots":3,"kind":"background","note":"Old colleagues in the Police Scotland forensics unit"},{"name":"Resources","dots":2,"kind":"background","note":"Wedding photography, which he hates"},{"name":"Safe House","dots":2,"kind":"background","note":"His darkroom in a Partick basement"},{"name":"Enemy","dots":1,"kind":"flaw","note":"A detective inspector who thinks he tampers with evidence"},{"name":"Dark Secret","dots":1,"kind":"flaw","note":"He kept negatives from a case that was officially closed"}],"convictions":[{"conviction":"The truth gets told, whatever it costs.","touchstone":"His sister Fiona, a nurse who thinks he needs therapy"},{"conviction":"Never let a victim become a statistic.","touchstone":"Maggie Doyle, mother of the girl in the photographs"}],"biography":{"born":"1991-02-27","turned":"2021-09-14","appearance":"Swept-back grey-streaked hair, a red tartan flannel coat, a scarf, and a camera on a worn strap.","features":"Chews the inside of his cheek while he thinks.","history":"Dez photographed bodies for Police Scotland for six years. Then one came back through the morgue doors without its blood and smiled at him. The report called it a mix-up. He kept the negatives, quit, and started pinning photographs to a wall. That wall became the Kelvin Street Cell’s evidence board."}}'::jsonb),
  ('htr-father-ruiz', 'hunter', 2, 'Father Ruiz', 'Faithful', '/portraits/hunter-priest.webp', 'A parish priest who saw what lived in the bell tower. His Drive is Atonement, and he has a lot to atone for.', '{"profile":{"name":"Father Tomás Ruiz","concept":"Parish priest with a sin to answer for","chronicle":"Glasgow by Night","cell":"The Kelvin Street Cell","creed":"Faithful","drive":"Atonement","ambition":"Cleanse St Mungo’s bell tower of the thing he let in.","desire":"To hear one confession that isn’t his own."},"attributes":{"Strength":2,"Dexterity":2,"Stamina":2,"Charisma":3,"Manipulation":1,"Composure":3,"Intelligence":3,"Wits":2,"Resolve":4},"skills":{"Occult":{"dots":3,"specialty":"Exorcism"},"Academics":{"dots":3,"specialty":"Theology"},"Insight":{"dots":3,"specialty":"Confession"},"Persuasion":{"dots":2},"Medicine":{"dots":2},"Etiquette":{"dots":2},"Leadership":{"dots":2},"Melee":{"dots":2},"Athletics":{"dots":1},"Drive":{"dots":1},"Awareness":{"dots":1},"Investigation":{"dots":1},"Politics":{"dots":1},"Intimidation":{"dots":1},"Performance":{"dots":1}},"edges":[{"name":"Repel the Unnatural","perks":[]},{"name":"Library","perks":["The diocesan archive: centuries of records on what hid in Glasgow’s churches"]}],"trackers":{"health":5,"willpower":7,"desperation":1,"danger":0},"advantages":[{"name":"Allies","dots":2,"kind":"background","note":"The faithful of his parish"},{"name":"Contacts","dots":2,"kind":"background","note":"A canon at the archdiocese"},{"name":"Safe House","dots":2,"kind":"background","note":"The rectory cellar, consecrated twice"},{"name":"Resources","dots":1,"kind":"background","note":"A priest’s stipend"},{"name":"Dark Secret","dots":1,"kind":"flaw","note":"He gave the bell-tower creature sanctuary, and people died"},{"name":"Enemy","dots":1,"kind":"flaw","note":"The thing in the bell tower remembers him"}],"convictions":[{"conviction":"No one is beyond saving, except what lives in the tower.","touchstone":"Mrs Agnelli, who arranges the flowers every Sunday"},{"conviction":"Protect the flock before yourself.","touchstone":"Alfie, the altar boy who still trusts him"}],"biography":{"born":"1962-05-08","turned":"2019-12-24","appearance":"Heavyset, thinning white hair, a brown leather jacket over his clerical collar, and a red scarf.","features":"Carries a rosary worn smooth on one side.","history":"Father Ruiz came to Glasgow from Seville in the nineties. On Christmas Eve in 2019 he opened the church to a stranger who asked for sanctuary, and the stranger never left the bell tower. Two parishioners were found drained that winter. He does not ask to be forgiven. He asks only to finish it."}}'::jsonb),
  ('htr-vesna-kovac', 'hunter', 3, 'Vesna Kovač', 'Underground', '/portraits/hunter-vesna.webp', 'Runs the cell’s burner phones, safehouses and forged papers. Hunts the thing that took her brother.', '{"profile":{"name":"Vesna Kovač","concept":"Smuggler who keeps the cell off the grid","chronicle":"Glasgow by Night","cell":"The Kelvin Street Cell","creed":"Underground","drive":"Vengeance","ambition":"Find the creature that took Luka, and end it.","desire":"To sleep in the same bed twice in a row."},"attributes":{"Strength":2,"Dexterity":4,"Stamina":2,"Charisma":2,"Manipulation":3,"Composure":3,"Intelligence":2,"Wits":3,"Resolve":1},"skills":{"Streetwise":{"dots":3,"specialty":"Black market"},"Stealth":{"dots":3},"Larceny":{"dots":3,"specialty":"Forged papers"},"Subterfuge":{"dots":2},"Technology":{"dots":2,"specialty":"Burner phones"},"Firearms":{"dots":2},"Drive":{"dots":2},"Awareness":{"dots":2},"Brawl":{"dots":1},"Melee":{"dots":1},"Athletics":{"dots":1},"Insight":{"dots":1},"Persuasion":{"dots":1},"Intimidation":{"dots":1},"Medicine":{"dots":1}},"edges":[{"name":"Improvised Gear","perks":[]},{"name":"Global Access","perks":["Papers that survive close inspection"]}],"trackers":{"health":5,"willpower":4,"desperation":1,"danger":0},"advantages":[{"name":"Safe House","dots":3,"kind":"background","note":"Three flats under three names: Govan, Dennistoun, Maryhill"},{"name":"Contacts","dots":2,"kind":"background","note":"Smugglers on the Clyde docks"},{"name":"Resources","dots":1,"kind":"background","note":"Cash, never a bank"},{"name":"Alternate Identity","dots":1,"kind":"background","note":"Vera Kowalski, cleaner"},{"name":"Enemy","dots":1,"kind":"flaw","note":"A gangster she owes for her first set of papers"},{"name":"Addiction","dots":1,"kind":"flaw","note":"Cigarettes, one after another"}],"convictions":[{"conviction":"Leave no one behind who can still be saved.","touchstone":"Mira, the girl she smuggled out of a blood farm"},{"conviction":"Never trust anything that doesn’t breathe.","touchstone":"Her mother in Split, who still waits for Luka"}],"biography":{"born":"1994-07-11","turned":"2020-03-02","appearance":"Dark hair pulled back, a heavy scarf, rings and an ear full of piercings, and a cigarette always burning.","features":"Never sits facing away from a door.","history":"Vesna and her brother Luka came to Glasgow on a container ship and forged papers. Luka took a job at a nightclub, and one night he walked out with the owner and never came back. The police shrugged. Vesna didn’t. She knows how to disappear, how to move people and how to get anything through customs, and now the cell uses all of it."}}'::jsonb)
on conflict (key) do update set
  game = excluded.game,
  sort = excluded.sort,
  name = excluded.name,
  faction = excluded.faction,
  portrait = excluded.portrait,
  summary = excluded.summary,
  sheet = excluded.sheet;

-- Refresh starter copies nobody has edited yet.
update public.characters c
set sheet = s.sheet, name = s.name, faction = s.faction, portrait = s.portrait, summary = s.summary
from public.starter_characters s
where c.starter_key = s.key and c.updated_at = c.created_at;

-- Give existing accounts the starters they don't have yet.
insert into public.characters (user_id, game, name, faction, portrait, summary, status, sheet, starter_key)
select u.id, s.game, s.name, s.faction, s.portrait, s.summary, 'finished', s.sheet, s.key
from auth.users u
cross join public.starter_characters s
where not exists (
  select 1 from public.characters c where c.user_id = u.id and c.starter_key = s.key
);
